package org.circus.core;
import java.io.*;
import java.nio.*;
import java.util.*;

/**Private physical-COM fixtures only. This proves guest ABI/control/lifetime
 *contracts, not native DirectSound calls or an adopted physical COM graph. */
public final class Pc1ComMemoryTests {
    private static int checks;
    private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
    private interface Work {void run()throws IOException;}
    private static void rejects(Work work,String message)throws IOException{boolean failed=false;try{work.run();}catch(IOException expected){failed=true;}check(failed,message);}
    private static Pc1GuestAddressSpace.ExternalOwner key(String role,String id)throws IOException{return new Pc1GuestAddressSpace.ExternalOwner(role,id);}
    private static Pc1ComMemory.Stack stack(final int... words){return index->{if(index<0||index>=words.length)throw new IOException("Fixture unknown stack word "+index);return words[index];};}
    private static final class Physical implements Pc1ComMemory.Binding {
        final Pc1ComMemory.Kind kind;final String table;final long pointer;int refs=2,volume=0,enters=0;boolean playing,earlyFailure;Work invocationHook;
        Physical(Pc1ComMemory.Kind kind,String table,long pointer){this.kind=kind;this.table=table;this.pointer=pointer;}
        public Pc1ComMemory.Kind kind(){return kind;}public long physicalIdentity(){return pointer;}public boolean live(){return refs>0;}public String contractId(){return "EXPLICIT_PRIVATE_COM_FIXTURE_V1";}
        public byte[] restorationProof()throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();DataOutputStream data=new DataOutputStream(out);data.writeUTF(table);data.writeInt(refs);data.writeInt(volume);data.writeBoolean(playing);return out.toByteArray();}
        public Pc1GuestAddressSpace.ExternalOwner vtableOwner(){try{return key(Pc1ComMemory.VTABLE_OWNER,table);}catch(IOException e){throw new AssertionError(e);}}
        public Pc1ComMemory.Leaf leaf(int slot)throws IOException{final Pc1ComMemory.Method method=Pc1ComMemory.method(kind,slot);final Pc1GuestAddressSpace.ExternalOwner owner=key(Pc1ComMemory.CALL_OWNER,table+"/"+slot);return new Pc1ComMemory.Leaf(){public Pc1GuestAddressSpace.ExternalOwner owner(){return owner;}public Pc1ComMemory.Method method(){return method;}public String contractId(){return "EXPLICIT_PRIVATE_COM_LEAF_V1";}public byte[] restorationProof(){return new byte[]{(byte)method.kind.ordinal(),(byte)method.slot};}public int invoke(Pc1ComMemory.Binding actual,Pc1ComMemory.Stack args)throws IOException{
            Physical target=(Physical)actual;target.enters++;if(target.invocationHook!=null)target.invocationHook.run();if(target.kind!=method.kind)throw new IOException("Fixture requires a different actual interface ABI");switch(method.name){case "AddRef":return ++target.refs;case "Release":return --target.refs;case "Stop":target.playing=false;return 0;case "SetVolume":target.volume=args.word(1);return 0;case "GetCaps":if(target.earlyFailure)return 0x80004005;args.word(1);return 0;default:return 0x12345678;}
        }};}
    }
    private static final class World {
        final Pc1GuestAddressSpace space;final Pc1NativeMemory bus;final Pc1ComMemory com;final byte[] cells=new byte[0x40];
        World()throws IOException{space=new Pc1GuestAddressSpace(Pc1GuestAddressSpace.Layout.imageHeapV1());final byte[] settings=new byte[Pc1NativeSettings.SIZE];bus=new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int n){return settings[n]&255;}public void write(int n,int v){settings[n]=(byte)v;}});bus.bindGuestAddressSpace(space);bus.bind(0xbc12c8,cells.length,new Pc1NativeMemory.Region(){public int read(int n){return cells[n]&255;}public void write(int n,int v){cells[n]=(byte)v;}});com=new Pc1ComMemory(space);}
    }
    private interface Writer {void write(DataOutput out)throws IOException;}
    private static byte[] save(Writer writer)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();writer.write(new DataOutputStream(bytes));return bytes.toByteArray();}
    private static DataInputStream input(byte[] bytes){return new DataInputStream(new ByteArrayInputStream(bytes));}
    private static class Rebinding implements Pc1ComMemory.Rebinder {
        long next=0x3456789000L;final Map<Pc1GuestAddressSpace.ExternalOwner,Physical> physical=new HashMap<>();boolean changedProof,collapse;
        public Pc1ComMemory.Leaf code(Pc1ComMemory.SavedCode saved)throws IOException{String id=saved.owner.id;String table=id.substring(0,id.lastIndexOf('/'));return new Physical(saved.method.kind,table,0).leaf(saved.method.slot);}
        public Pc1ComMemory.Binding object(Pc1ComMemory.SavedObject saved)throws IOException{DataInputStream in=input(saved.restorationProof());String table=in.readUTF();Physical p=new Physical(saved.kind,table,collapse?0x3456789000L:next);next+=16;p.refs=in.readInt();p.volume=in.readInt();p.playing=in.readBoolean();if(changedProof&&saved.live)p.volume++;physical.put(saved.owner,p);return p;}
    }
    public static int run()throws IOException{
        checks=0;World w=new World();Physical a=new Physical(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,"secondary",0x1234567890L),b=new Physical(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,"secondary",0x1234567898L),primary=new Physical(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,"primary",0x12345678a0L),device=new Physical(Pc1ComMemory.Kind.DIRECT_SOUND,"device",0x12345678a8L);
        Pc1ComMemory.ObjectRef ar=w.com.register(key(Pc1ComMemory.INTERFACE_OWNER,"a"),a),br=w.com.register(key(Pc1ComMemory.INTERFACE_OWNER,"b"),b),pr=w.com.register(key(Pc1ComMemory.INTERFACE_OWNER,"p"),primary),dr=w.com.register(key(Pc1ComMemory.INTERFACE_OWNER,"d"),device);int at=w.space.readI32(ar.address),bt=w.space.readI32(br.address),pt=w.space.readI32(pr.address),dt=w.space.readI32(dr.address);
        check(ar.address!=(int)a.pointer,"Physical64 pointer is not truncated into guest DWORD");check(at==bt&&pt!=at,"Verified secondary class shares table while primary remains distinct");check(w.com.borrowedVtable(a.vtableOwner()).capacity()==84&&w.com.borrowedVtable(device.vtableOwner()).capacity()==44,"Only public COM DWORD extents are owned");rejects(()->w.space.read(ar.address+4),"Unknown private COM bytes are not zero padded");rejects(()->w.space.read(at+84),"Unknown vtable suffix is not silently known");int stop=w.space.readI32(at+72),volume=w.space.readI32(at+60);rejects(()->w.space.read(stop),"Typed code leaf has no fabricated machine instructions");
        int negativeCell=0xbc12d0-8;w.space.writeI32(negativeCell,ar.address);Pc1ComMemory.Call stopCall=w.com.resolveCell(negativeCell,72);check(stopCall.method.name.equals("Stop")&&stopCall.object==ar,"Negative aliased pointer cell resolves normal COM object without ten-slot clamp");a.playing=true;w.com.invoke(stopCall,stack(ar.address),1);check(!a.playing&&a.enters==1,"Required physical leaf actually runs");
        w.com.borrowedVtable(a.vtableOwner()).putInt(72,volume);Pc1ComMemory.Call changed=w.com.resolveCell(negativeCell,72);check(changed.method.name.equals("SetVolume"),"Mutable direct vtable changes the selected leaf");rejects(()->w.com.invoke(changed,stack(ar.address,-700),1),"Redirected cleanup mismatch is a late stack boundary");check(a.volume==-700&&a.enters==2,"Actual selected leaf side effect precedes cleanup fault");w.com.invoke(changed,stack(br.address,-1200),2);check(b.volume==-1200&&a.volume==-700,"Caller THIS association may differ from interface used for function fetch");
        w.space.writeI32(at+72,stop);check(w.com.borrowedVtable(a.vtableOwner()).getInt(72)==stop,"Bus and direct vtable share sole bytes");ar.borrowedHeader().putInt(0,pt);check(w.com.resolveCell(negativeCell,72).leafAddress==w.space.readI32(pt+72),"Direct header replacement is read at the next actual call");w.space.writeI32(ar.address,at);
        int count=w.space.mappingCount();Pc1ComMemory.ObjectRef alias=w.com.register(key(Pc1ComMemory.INTERFACE_OWNER,"alias-a"),a);check(alias==ar&&w.space.mappingCount()==count&&a.refs==2,"Same physical interface/QI alias adds no fabricated ref or allocation");
        rejects(()->w.com.register(key(Pc1ComMemory.INTERFACE_OWNER,"conflicting-alias"),new Physical(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,"primary",a.pointer)),"Same physical pointer cannot silently acquire a different vtable class");
        int forged=Pc1NativeMemory.SETTINGS_BASE+16;w.space.writeI32(forged,at);w.space.writeI32(negativeCell,forged);Pc1ComMemory.Call forgedCall=w.com.resolveCell(negativeCell,72);check(forgedCall.object==null&&forgedCall.method.name.equals("Stop"),"Known arbitrary header bytes are read before physical THIS admission");rejects(()->w.com.invoke(forgedCall,stack(forged),1),"Unknown THIS does not become a numeric object ID");w.space.writeI32(negativeCell,ar.address);
        int caps=w.space.readI32(at+12);w.space.writeI32(at+72,caps);a.earlyFailure=true;int before=a.enters;rejects(()->w.com.invoke(w.com.resolveCell(negativeCell,72),stack(ar.address),1),"Early OS leaf return retains its actual later cleanup mismatch");check(a.enters==before+1,"Unused callee operands are not eagerly fetched before proved early failure");a.earlyFailure=false;rejects(()->w.com.invoke(w.com.resolveCell(negativeCell,72),stack(ar.address),1),"Required missing stack word fails in selected leaf");w.space.writeI32(at+72,stop);
        w.space.writeI32(at+72,0x12345678);rejects(()->w.com.resolveCell(negativeCell,72),"Unknown current raw call pointer is required, never default no-op");w.space.writeI32(at+72,stop);
        Pc1ComMemory.Call release=w.com.resolve(ar.address,8);check(w.com.invoke(release,stack(ar.address),1)==1&&w.space.contains(ar.address),"Nonzero actual Release keeps borrowed header live");check(w.com.invoke(release,stack(ar.address),1)==0&&!w.space.contains(ar.address),"Actual zero Release retires header via provider, no helper refcount");check(w.space.readI32(negativeCell)==ar.address,"Retirement never repairs raw pointer cell");rejects(()->w.com.resolveCell(negativeCell,72),"Freed header is unknown memory, not a cached COM object");Physical reused=new Physical(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,"secondary",0x2345678900L);Pc1ComMemory.ObjectRef reuse=w.com.register(key(Pc1ComMemory.INTERFACE_OWNER,"reuse"),reused);check(reuse.address==ar.address&&w.com.resolveCell(negativeCell,72).object==reuse,"Only shared Guest policy decides retired-address reuse; stale rawword now resolves new allocation");
        World other=new World();rejects(()->other.com.invoke(stopCall,stack(ar.address),1),"Captured call cannot be reused across restored guest worlds");check(Pc1ComMemory.method(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,11).argumentWords==8&&Pc1ComMemory.method(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,19).argumentWords==5,"Public stdcall32 Lock/Unlock argument shapes include THIS");rejects(()->Pc1ComMemory.method(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,21),"No invented IDirectSoundBuffer8 suffix");
        //Raw mutable ABI images survive, including an unresolved current leaf.
        br.borrowedHeader().putInt(0,pt);w.space.writeI32(at+72,volume);w.space.writeI32(at+80,0x51515151);byte[] imageBytes=save(w.com::save);Pc1ComMemory.Image image=Pc1ComMemory.loadImage(input(imageBytes));byte[] layoutBytes=save(out->w.space.saveLayout(out,lease->-1));Pc1GuestAddressSpace.Image layout=Pc1GuestAddressSpace.loadLayout(input(layoutBytes));World restored=new World();Rebinding binding=new Rebinding();Pc1ComMemory copy=Pc1ComMemory.restore(image,restored.space,layout,binding);restored.space.restoreLayout(layout,Collections.emptyList());
        check(Arrays.equals(imageBytes,save(copy::save)),"COM codec roundtrips exact sole header/vtable bytes and typed graph descriptors");check(copy.findOwner(br.owner).borrowedHeader().position()==0&&copy.borrowedVtable(b.vtableOwner()).position()==0,"Restored native direct views have exact base/position");check(restored.space.readI32(br.address)==pt&&restored.space.readI32(at+80)==0x51515151,"Header replacement and currently unknown leaf are preserved without default reset");rejects(()->copy.resolve(reuse.address,80),"Unresolved saved leaf faults at later call, not snapshot load");
        for(Physical physical:binding.physical.values())check(physical.enters==0,"Restore issues no fabricated AddRef/Release/Play/Stop calls");check(copy.resolve(reuse.address,72).method.name.equals("SetVolume"),"Restored mutable leaf selection comes from saved ABI bytes");copy.invoke(copy.resolve(reuse.address,72),stack(reuse.address,-1700),2);check(binding.physical.get(reuse.owner).volume==-1700,"Restored selected leaf uses newly rebound physical object");
        World bad=new World();Rebinding wrong=new Rebinding();wrong.changedProof=true;rejects(()->Pc1ComMemory.restore(image,bad.space,layout,wrong),"Changed physical graph proof is rejected");check(bad.space.mappingCount()==0,"All physical proofs validated before publishing any external guest owner");World collapsed=new World();Rebinding merged=new Rebinding();merged.collapse=true;rejects(()->Pc1ComMemory.restore(image,collapsed.space,layout,merged),"Distinct retained/live objects cannot collapse onto one physical interface");check(collapsed.space.mappingCount()==0,"Collapsed graph rejection stages no guest mappings");
        Physical live=binding.physical.get(reuse.owner);live.invocationHook=()->save(copy::save);rejects(()->copy.invoke(copy.resolve(reuse.address,72),stack(reuse.address,-1),2),"Snapshot during physical COM call is rejected");live.invocationHook=null;
        //The COM codec contains external payload/descriptors only. Layout is
        //restored once by the Pool's address-space operation above.
        check(layout.mappingCount()>image.objects().size()&&image.code().size()==53,"Sole layout covers known code/table/live-header mappings, not duplicated physical payloads");check(copy.callAddress(key(Pc1ComMemory.CALL_OWNER,"secondary/15"))==restored.space.readI32(at+72)&&copy.vtableAddress(b.vtableOwner())==at,"Native bridge obtains exact registered addresses without numeric slot cache");int enters=live.enters;copy.detachViews();check(restored.space.mappingCount()==0&&live.enters==enters,"Staging abort detaches only guest mappings, no fabricated physical Release");rejects(()->copy.resolve(reuse.address,72),"Detached world cannot resolve a retained old ABI view");rejects(()->save(copy::save),"Detached views cannot be saved as an adopted live graph");
        Pc1GuestAddressSpace tiny=new Pc1GuestAddressSpace(new Pc1GuestAddressSpace.Layout(0x20000000,0x20000008L,8));Pc1ComMemory partial=new Pc1ComMemory(tiny);Pc1GuestAddressSpace.ExternalOwner pending=key(Pc1ComMemory.INTERFACE_OWNER,"allocation-prefix");rejects(()->partial.register(pending,new Physical(Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER,"secondary",0x4567890000L)),"Guest allocation failure preserves a strict incomplete publication boundary");check(tiny.mappingCount()==1,"Already allocated interface-prefix owner is not silently rolled back");rejects(()->tiny.readI32(partial.findOwner(pending).address),"Incomplete header does not invent readable zero DWORD");rejects(()->partial.findOwner(pending).borrowedHeader(),"Incomplete ABI cannot export a misleading direct view");rejects(()->save(partial::save),"Unknown partial vtable construction cannot masquerade as an adopted graph snapshot");partial.detachViews();check(tiny.mappingCount()==0,"Explicit staging abort can detach incomplete ABI allocation without releasing physical owner");return checks;
    }
    public static void main(String[] args)throws Exception{System.out.println("Pc1ComMemoryTests PASS "+run()+"; explicit fixture leaves, known public ABI/raw aliases/lifetime only; physical DS graph integration pending");}
}
